cd /d/tmp/ss-empower && cat admin/src/components/expansion/expansion.css | cut -c1-600; grep -rln "expansion_resources" web/src | head; node -e '
const L=h=>{const c=[1,3,5].map(i=>parseInt(h.slice(i,i+2),16)/255).map(v=>v<=0.03928?v/12.92:((v+0.055)/1.055)**2.4);return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2]};
const r=(a,b)=>{const x=L(a),y=L(b);return ((Math.max(x,y)+0.05)/(Math.min(x,y)+0.05)).toFixed(2)};
for (const [f,b] of [["#d1b266","#131416"],["#d1b266","#1a1b1e"],["#d1b266","#222428"],["#cfc7bc","#131416"],["#a6b0be","#1a1b1e"],["#667085","#131416"],["#667085","#1a1b1e"],["#131416","#d1b266"],["#e8a045","#0b0a08"],["#f1f5f9","#131416"]]) console.log(f,"on",b,r(f,b))'

content.content:
.expansion{height:100dvh;overflow:auto;background:#131416;color:#edf0f5;font-family:var(--font-dm);font-size:14px}.expansion-founder{height:auto;min-height:100%;overflow:visible}.ex-header{display:flex;justify-content:space-between;align-items:center;gap:20px;min-height:92px;padding:20px 36px;border-bottom:1px solid #303136;background:#18191b}.ex-brand{display:flex;align-items:center;gap:12px;color:#f5f5f5;text-decoration:none;font-size:17px;letter-spacing:.13em;font-weight:700}.ex-brand small{display:block;font-size:8px;letter-spacing:.19em;color:#c3a86c;margin-top:5px}.ex-header-right{displa

.ex-money,.ex-metric>strong{white-space:nowrap;font-variant-numeric:tabular-nums}

/* Checkpoint 5: research allocation, recognition and profiles */
.ex-research{border:1px solid var(--ex-line,rgba(255,255,255,.14));border-radius:12px;padding:16px;margin:12px 0;background:rgba(255,255,255,.03)}
.ex-research dl,.ex-checks ul{margin:8px 0 0;padding-left:0;list-style:none}
.ex-checks{margin:12px 0;padding:12px;border-radius:10px;border:1px dashed rgba(255,255,255,.2)}
.ex-history{padding-left:18px;font-size:.9rem}
.ex-recognition-body{display:grid;grid-template-columns:auto 1fr;gap:24px;align-items:center}
.ex-badge-art{filter:drop-shadow(0 6px 18px rgba(201,162,74,.28));max-width:100%;height:auto}
.ex-note{font-size:.9rem;opacity:.8}
@media (max-width:640px){.ex-recognition-body{grid-template-columns:1fr;justify-items:center;text-align:center}}
